/**
 * Animated film grain, generated by an SVG turbulence filter rather than a
 * tiled PNG. Blended with soft-light so it unifies the dark palette instead of
 * washing it out.
 */
export default function Grain() {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none fixed inset-0 z-[100] overflow-hidden mix-blend-soft-light"
      style={{ opacity: 0.5 }}
    >
      <svg className="grain-layer absolute -inset-[100%] h-[300%] w-[300%]">
        <filter id="aqualume-grain">
          <feTurbulence
            type="fractalNoise"
            baseFrequency="0.82"
            numOctaves="3"
            stitchTiles="stitch"
          />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter="url(#aqualume-grain)" />
      </svg>
    </div>
  );
}
